def count_between(values, low, high):
    if low > high:
        raise ValueError("low exceeds high")
    lo, hi = 0, len(values)
    while lo < hi:
        mid = (lo + hi) // 2
        if values[mid] < low:
            lo = mid + 1
        else:
            hi = mid
    first = lo
    lo, hi = 0, len(values)
    while lo < hi:
        mid = (lo + hi) // 2
        if values[mid] <= high:
            lo = mid + 1
        else:
            hi = mid
    return lo - first

print(count_between([1, 2, 2, 5, 8], 2, 5))
print(count_between([1, 8], 3, 6))
print(count_between([], 0, 1))
try:
    count_between([1], 2, 1)
except ValueError:
    print("ValueError")

def insert_sorted(values, value, side):
    if side not in ("left", "right"):
        raise ValueError("invalid side")
    lo, hi = 0, len(values)
    while lo < hi:
        mid = (lo + hi) // 2
        if values[mid] < value or (side == "right" and values[mid] == value):
            lo = mid + 1
        else:
            hi = mid
    result = list(values)
    result.insert(lo, value)
    return result, lo

print(insert_sorted([1, 2, 2, 5], 2, "left"))
print(insert_sorted([1, 2, 2, 5], 2, "right"))
print(insert_sorted([], 4, "left"))
try:
    insert_sorted([1], 2, "middle")
except ValueError:
    print("ValueError")
